遍历字符串的每个字符，判断是否为元音字母（含大小写），计数并输出。参考程序：

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    string s;
    cin >> s;
    int cnt = 0;
    for (int i = 0; i < (int)s.size(); i++) {
        char c = s[i];
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' ||
            c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U')
            cnt++;
    }
    cout << cnt << endl;
    return 0;
}
```

枚举 a 从 1 到 n，令 b = k - a，若 b > a 且 b ≤ n 即为一组合法数对，满足按 a 升序输出；全部枚举完无输出则打印 none。参考程序：

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, k;
    cin >> n >> k;
    bool found = false;
    for (int a = 1; a <= n; a++) {
        int b = k - a;
        if (b > a && b <= n) {
            cout << a << " " << b << endl;
            found = true;
        }
    }
    if (!found) cout << "none" << endl;
    return 0;
}
```
